 EXECUTE 'SELECT jsonb_object_agg(v.signature,jsonb_build_object(''signature'',v.signature,''oid'',p.oid::bigint,''owner'',pg_get_userbyid(p.proowner),''acl'',p.proacl::text,''config'',to_jsonb(p.proconfig),''secdef'',p.prosecdef,''volatility'',p.provolatile::text,''language'',l.lanname,''source_md5'',md5(p.prosrc),''ddl_md5'',md5(pg_get_functiondef(p.oid)))) FROM (VALUES (''public.mission_generic_room_state_v1(uuid)'')) v(signature) JOIN pg_proc p ON p.oid=to_regprocedure(v.signature) JOIN pg_language l ON l.oid=p.prolang' INTO heads;
 IF ((SELECT count(*) FROM jsonb_object_keys(heads))=1) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST_INSTALL_HEADER_COUNT' USING ERRCODE='40001';END IF;
 IF (((heads->'public.mission_generic_room_state_v1(uuid)')-'oid'-'ddl_md5')='{"acl":"{postgres=X/postgres,authenticated=X/postgres}","config":["search_path=\"\""],"language":"plpgsql","owner":"postgres","secdef":true,"signature":"public.mission_generic_room_state_v1(uuid)","source_md5":"d651c670852fae08e91a4dc71ae806f1","volatility":"v"}'::jsonb) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'REQUEST_INSTALL_ATTRS' USING ERRCODE='40001';END IF;
